// ComplianceFinding is the OCSF "compliance_finding" event class (class_uid 2003). Compliance
// Finding events describe results of evaluations performed against resources, to check compliance
// with various Industry Frameworks or Security Standards such as NIST SP 800-53, CIS AWS
// Foundations Benchmark v1.4.0, ISO/IEC 27001 etc. Note: if the event producer is a security
// control, the security_control profile should be applied and its attacks information, if present,
// should be duplicated into the finding_info object. Note: If the Finding is an incident, i.e.
// requires incident workflow, also apply the incident profile or aggregate this finding into an
// Incident Finding .
type ComplianceFinding struct {
	// The normalized caption of action_id .
	Action string `json:"action,omitempty"`
	// The action taken by a control or other policy-based system leading to an outcome or
	// disposition. An unknown action may still correspond to a known disposition. Refer to
	// disposition_id for the outcome of the action.
	ActionID int `json:"action_id,omitempty"`
	// The normalized identifier of the finding activity. Use 1 (Create) when a finding is first
	// generated, 2 (Update) when an existing finding is modified (e.g., severity change, new
	// evidence), and 3 (Close) when a finding is resolved or dismissed.
	ActivityID int `json:"activity_id"`
	// The finding activity name, as defined by the activity_id . When activity_id is 99 (Other),
	// this must contain the source-specific activity label.
	ActivityName string `json:"activity_name,omitempty"`
	// The user, process, or service that initiated the activity on the host. For system-level
	// events this is typically a process; for IAM events it is typically a user or role.
	Actor *objects.Actor `json:"actor,omitempty"`
	// Describes details about a typical API (Application Programming Interface) call.
	API *objects.API `json:"api,omitempty"`
	// The details of the user assigned to an Incident.
	Assignee *objects.User `json:"assignee,omitempty"`
	// The details of the group assigned to an Incident.
	AssigneeGroup *objects.Group `json:"assignee_group,omitempty"`
	// An array of MITRE ATT&CK® objects describing identified tactics, techniques &
	// sub-techniques. The objects are compatible with MITRE ATLAS™ tactics, techniques &
	// sub-techniques.
	Attacks []objects.Attack `json:"attacks,omitempty"`
	// One or more cryptographic attestation objects over an event, each providing integrity,
	// authenticity, and non-repudiation. Independent attesters over the same event — for example
	// a producer at write time and a downstream processor at ingest — each contribute a separate
	// attestation, distinct from co-signers on a single attestation, which share its signatures
	// array. Carried on the record_integrity profile; the object itself is domain-agnostic.
	AttestationList []objects.Attestation `json:"attestation_list,omitempty"`
	// Provides details about an authorization, such as authorization outcome, and any associated
	// policies related to the activity/event.
	Authorizations []objects.Authorization `json:"authorizations,omitempty"`
	// The event category name, as defined by the category_uid value. The value must match the
	// caption defined for the corresponding category_uid enum value (e.g., "Findings" for
	// category_uid: 2 ).
	CategoryName string `json:"category_name,omitempty"`
	// The category unique identifier of the event. Each event class belongs to exactly one
	// category. Producers and mappers must set this to the category defined by the event class
	// being used.
	CategoryUID int `json:"category_uid"`
	// The event class name, as defined by the class_uid value. The value must match the caption
	// defined for the corresponding class_uid (e.g., "Detection Finding" for class_uid: 2004 ).
	ClassName string `json:"class_name,omitempty"`
	// The unique identifier of a class. A class describes the attributes available in an event.
	// Producers and mappers must set this to the uid defined in the event class definition. For
	// example, Detection Finding is 2004 .
	ClassUID int `json:"class_uid"`
	// Describes details about the Cloud environment where the event or finding was created.
	Cloud *objects.Cloud `json:"cloud,omitempty"`
	// A user provided comment about the finding.
	//
	// Deprecated: Use the notes attribute instead.
	Comment string `json:"comment,omitempty"`
	// The compliance object provides context to compliance findings (e.g., a check against a
	// specific regulatory or best practice framework such as CIS, NIST etc.) and contains
	// compliance related details.
	Compliance *objects.Compliance `json:"compliance"`
	// The confidence, normalized to the caption of the confidence_id value. In the case of
	// 'Other', it is defined by the event source.
	Confidence string `json:"confidence,omitempty"`
	// The normalized confidence refers to the accuracy of the analytics that produced the finding.
	// An analytic with a low confidence means that the finding scope is wide and may create
	// finding reports that are noisy or may not be malicious in nature.
	ConfidenceID int `json:"confidence_id,omitempty"`
	// The confidence score as reported by the source or assigned by the analyst expressed on a
	// source-specific numeric scale. This score provides finer-grained confidence information than
	// the categorical confidence_id value. If confidence_id is 99 'Other', it should reflect the
	// the same assessment as confidence if both are populated.
	ConfidenceScore int `json:"confidence_score,omitempty"`
	// The number of events aggregated into this single record. Only populate for aggregate events.
	// When set, start_time and end_time should also be provided to define the aggregation window.
	Count int `json:"count,omitempty"`
	// Describes the affected device/host. It can be used in conjunction with resources or when
	// there are multiple devices affected. E.g. The role of the device as target or actor,
	// specific details about a cloud resource compute instance, etc. If a single device is the
	// source of the finding, use the Host profile and populate device .
	Device *objects.Device `json:"device,omitempty"`
	// The disposition name, normalized to the caption of the disposition_id value. In the case of
	// 'Other', it is defined by the event source.
	Disposition string `json:"disposition,omitempty"`
	// Describes the outcome or action taken by a security control, such as access control checks,
	// malware detections or various types of policy violations.
	DispositionID int `json:"disposition_id,omitempty"`
	// The elapsed time of the aggregation window in milliseconds, from start_time to end_time .
	// Only populate for aggregate events ( count > 1). The value should equal end_time -
	// start_time .
	Duration int64 `json:"duration,omitempty"`
	// The time of the most recent event or finding that contributed to this finding.
	EndTime int64 `json:"end_time,omitempty"`
	// The additional information from an external data source, which is associated with the event
	// or a finding. For example add location information for the IP address in the DNS answers:
	// [{"name": "answers.ip", "value": "92.24.47.250", "type": "location", "data": {"city":
	// "Socotra", "continent": "Asia", "coordinates": [-25.4153, 17.0743], "country": "YE", "desc":
	// "Yemen"}}]
	Enrichments []objects.Enrichment `json:"enrichments,omitempty"`
	// Describes various evidence artifacts associated with the compliance finding.
	Evidences []objects.Evidences `json:"evidences,omitempty"`
	// Describes the supporting information about a generated finding.
	FindingInfo *objects.FindingInfo `json:"finding_info"`
	// The firewall rule that pertains to the control that triggered the event, if applicable.
	FirewallRule *objects.FirewallRule `json:"firewall_rule,omitempty"`
	// The impact , normalized to the caption of the impact_id value. In the case of 'Other', it is
	// defined by the event source.
	Impact string `json:"impact,omitempty"`
	// The normalized impact of the incident or finding. Per NIST, this is the magnitude of harm
	// that can be expected to result from the consequences of unauthorized disclosure,
	// modification, destruction, or loss of information or information system availability.
	ImpactID int `json:"impact_id,omitempty"`
	// The impact as an integer value of the finding, valid range 0-100.
	ImpactScore int `json:"impact_score,omitempty"`
	// Indicates that the event is considered to be an alertable signal. Should be set to true if
	// disposition_id = Alert among other dispositions, and/or risk_level_id or severity_id of the
	// event is elevated. Not all control events will be alertable, for example if disposition_id =
	// Exonerated or disposition_id = Allowed .
	IsAlert *bool `json:"is_alert,omitempty"`
	// A determination based on analytics as to whether a potential breach was found.
	IsSuspectedBreach *bool `json:"is_suspected_breach,omitempty"`
	// A list of Malware objects, describing details about the identified malware.
	Malware []objects.Malware `json:"malware,omitempty"`
	// Describes details about the scan job that identified malware on the target system.
	MalwareScanInfo *objects.MalwareScanInfo `json:"malware_scan_info,omitempty"`
	// A human-readable description of the event, as defined by the source. This should be a
	// concise, meaningful summary suitable for display in a UI or alert notification - not a raw
	// log line. For example: "User john_doe logged in from 10.0.0.1." rather than a raw syslog
	// string.
	Message string `json:"message,omitempty"`
	// The metadata object describes the event producer, schema version, and processing
	// information. Producers and mappers must populate metadata.product to identify the data
	// source, and metadata.version to indicate the OCSF schema version used. Consumers rely on
	// this to interpret the event correctly.
	Metadata *objects.Metadata `json:"metadata"`
	// Additional notes related to the finding. Each note in the array can include a comment, the
	// user who made the comment, the time when the note was created, and the time when the note
	// was last modified (typically by the same user). Notes can be used to provide additional
	// context, explanations, or observations by analysts related to the finding over time.
	Notes []objects.Note `json:"notes,omitempty"`
	// The observables array surfaces key indicators and entities from the event or finding in a
	// single, consistent location for downstream correlation and detection. Each entry references
	// an attribute path within the event (e.g., src_endpoint.ip ) along with its type and value,
	// enabling consumers to extract IOCs without parsing the full event structure.
	Observables []objects.Observable `json:"observables,omitempty"`
	// The OSINT (Open Source Intelligence) object contains details related to an indicator such as
	// the indicator itself, related indicators, geolocation, registrar information, subdomains,
	// analyst commentary, and other contextual information. This information can be used to
	// further enrich a detection or finding by providing decisioning support to other analysts and
	// engineers.
	OSINT []objects.OSINT `json:"osint,omitempty"`
	// The policy that pertains to the control that triggered the event, if applicable. For example
	// the name of an anti-malware policy or an access control policy.
	Policy *objects.Policy `json:"policy,omitempty"`
	// The priority, normalized to the caption of the priority_id value. In the case of 'Other', it
	// is defined by the event source.
	Priority string `json:"priority,omitempty"`
	// The normalized priority. Priority identifies the relative importance of the incident or
	// finding. It is a measurement of urgency.
	PriorityID int `json:"priority_id,omitempty"`
	// The original event/finding data as received from the source, before normalization into OCSF.
	// Populate this with the verbatim log line, JSON payload, or other native format for forensic
	// and debugging purposes. This field is not intended for structured querying - use the
	// normalized OCSF attributes instead.
	RawData string `json:"raw_data,omitempty"`
	// A fingerprint (hash) of the raw_data content. Use this to verify the integrity of the
	// original event data or to deduplicate events.
	RawDataHash *objects.Fingerprint `json:"raw_data_hash,omitempty"`
	// The size of the original event data (as captured in raw_data ) in bytes, before OCSF
	// normalization. Useful for metering and capacity planning.
	RawDataSize int64 `json:"raw_data_size,omitempty"`
	// Describes the recommended remediation steps to address identified issue(s).
	Remediation *objects.Remediation `json:"remediation,omitempty"`
	// Describes details about the resource that is the subject of the compliance check.
	//
	// Deprecated: Use the resources attribute instead.
	Resource *objects.ResourceDetails `json:"resource,omitempty"`
	// Describes details about the resource/resources that are the subject of the compliance check.
	Resources []objects.ResourceDetails `json:"resources,omitempty"`
	// Describes the risk associated with the finding.
	RiskDetails string `json:"risk_details,omitempty"`
	// The risk level, normalized to the caption of the risk_level_id value.
	RiskLevel string `json:"risk_level,omitempty"`
	// The normalized risk level id.
	RiskLevelID int `json:"risk_level_id,omitempty"`
	// The risk score as reported by the event source.
	RiskScore int `json:"risk_score,omitempty"`
	// The event/finding severity label, normalized to the caption of the severity_id value. When
	// severity_id is 99 (Other), this attribute must contain the source-specific severity label.
	// For all other values, this should match the caption defined for that severity_id enum value
	// (e.g., "High" for severity_id: 4 ).
	Severity string `json:"severity,omitempty"`
	// The normalized identifier of the event/finding severity. The normalized severity is a
	// measurement the effort and expense required to manage and resolve an event or incident.
	// Smaller numerical values represent lower impact events, and larger numerical values
	// represent higher impact events.
	SeverityID int `json:"severity_id"`
	// A Url link used to access the original incident.
	SrcURL string `json:"src_url,omitempty"`
	// The time of the earliest event or finding that contributed to this finding.
	StartTime int64 `json:"start_time,omitempty"`
	// The finding lifecycle status label, normalized to the caption of the status_id value. When
	// status_id is 99 (Other), this must contain the source-specific status label.
	Status string `json:"status,omitempty"`
	// The source-specific status or error code as reported by the event source. For example, a
	// Windows logon failure code ( 0x18 ), an HTTP response code ( 403 ), or an AWS API error
	// code. This preserves the original code for detailed troubleshooting beyond what status_id
	// conveys.
	StatusCode string `json:"status_code,omitempty"`
	// A human-readable description providing additional context about the event outcome. Use this
	// to convey details that go beyond the normalized status_id and source-specific status_code ,
	// such as a failure reason or error message. For example: "Account locked after 5 failed
	// attempts." .
	StatusDetail string `json:"status_detail,omitempty"`
	// The normalized finding lifecycle status identifier. Unlike the status of an activity event,
	// which indicates the success or failure of the activity, finding status tracks the review and
	// triage workflow: whether the finding is new, being investigated, suppressed, or resolved.
	// Producers should set this to reflect the current state of the finding in their system (e.g.,
	// 1 for newly created findings, 4 when remediated).
	StatusID int `json:"status_id,omitempty"`
	// The linked ticket in the ticketing system.
	//
	// Deprecated: Use tickets instead.
	Ticket *objects.Ticket `json:"ticket,omitempty"`
	// The associated ticket(s) in the ticketing system. Each ticket contains details like ticket
	// ID, status, etc.
	Tickets []objects.Ticket `json:"tickets,omitempty"`
	// The finding creation time - when the finding was first generated, not when the underlying
	// activity occurred. For the time range of contributing events, use start_time and end_time .
	Time int64 `json:"time"`
	// The number of minutes that the reported event time is ahead or behind UTC, in the range
	// -1,080 to +1,080. This allows consumers to reconstruct the local time at the event source.
	// For example, US Eastern Standard Time is -300 . Populate this when the source provides local
	// time zone information.
	TimezoneOffset int `json:"timezone_offset,omitempty"`
	// The event/finding type name, combining the class and activity (e.g., "Detection Finding:
	// Create" ). The value must match the class_name and activity_name joined by ": " .
	TypeName string `json:"type_name,omitempty"`
	// The event/finding type ID. It identifies the event's semantics and structure. Producers and
	// mappers must compute this as class_uid * 100 + activity_id . It uniquely identifies the
	// combination of event class and activity across the entire schema. For example, Detection
	// Finding: Create is 200401 .
	TypeUID int64 `json:"type_uid"`
	// A container for source-specific attributes that do not map to any defined OCSF attribute.
	// Use this to preserve valuable source data that would otherwise be lost during normalization.
	// The keys and values are specific to the event source. Note: Consumers should not rely on a
	// stable structure within this field. The preferred approach to unmapped attributes is to
	// create a custom extension with the desired structure.
	Unmapped map[string]any `json:"unmapped,omitempty"`
	// The Vendor Attributes object can be used to represent values of attributes populated by the
	// Vendor/Finding Provider. It can help distinguish between the vendor-provided values and
	// consumer-updated values, of key attributes like severity_id . The original finding producer
	// should not populate this object. It should be populated by consuming systems that support
	// data mutability.
	VendorAttributes *objects.VendorAttributes `json:"vendor_attributes,omitempty"`
	// The verdict assigned to an Incident finding.
	Verdict string `json:"verdict,omitempty"`
	// The normalized verdict of an Incident.
	VerdictID int `json:"verdict_id,omitempty"`
}

// ComplianceFindingActionID values for ComplianceFinding.ActionID (Action ID).
const (
	// The action was unknown. The disposition_id attribute may still be set to a non-unknown
	// value, for example 'Custom Action', 'Challenge'.
	ComplianceFindingActionIDUnknown = 0
	// The activity was allowed. The disposition_id attribute should be set to a value that
	// conforms to this action, for example 'Allowed', 'Approved', 'Delayed', 'No Action', 'Count'
	// etc.
	ComplianceFindingActionIDAllowed = 1
	// The attempted activity was denied. The disposition_id attribute should be set to a value
	// that conforms to this action, for example 'Blocked', 'Rejected', 'Quarantined', 'Isolated',
	// 'Dropped', 'Access Revoked, etc.
	ComplianceFindingActionIDDenied = 2
	// The activity was observed, but neither explicitly allowed nor denied. This is common with
	// IDS and EDR controls that report additional information on observed behavior such as TTPs.
	// The disposition_id attribute should be set to a value that conforms to this action, for
	// example 'Logged', 'Alert', 'Detected', 'Count', etc.
	ComplianceFindingActionIDObserved = 3
	// The activity was modified, adjusted, or corrected. The disposition_id attribute should be
	// set appropriately, for example 'Restored', 'Corrected', 'Delayed', 'Captcha', 'Tagged'.
	ComplianceFindingActionIDModified = 4
	// The action is not mapped. See the action attribute which contains a data source specific
	// value.
	ComplianceFindingActionIDOther = 99
)

