// SecurityFindingDispositionID values for SecurityFinding.DispositionID (Disposition ID).
const (
	// The disposition is unknown.
	SecurityFindingDispositionIDUnknown = 0
	// Granted access or allowed the action to the protected resource.
	SecurityFindingDispositionIDAllowed = 1
	// Denied access or blocked the action to the protected resource.
	SecurityFindingDispositionIDBlocked = 2
	// A suspicious file or other content was moved to a benign location.
	SecurityFindingDispositionIDQuarantined = 3
	// A session was isolated on the network or within a browser.
	SecurityFindingDispositionIDIsolated = 4
	// A file or other content was deleted.
	SecurityFindingDispositionIDDeleted = 5
	// The request was detected as a threat and resulted in the connection being dropped.
	SecurityFindingDispositionIDDropped = 6
	// A custom action was executed such as running of a command script. Use the message attribute
	// of the base class for details.
	SecurityFindingDispositionIDCustomAction = 7
	// A request or submission was approved. For example, when a form was properly filled out and
	// submitted. This is distinct from 1 'Allowed'.
	SecurityFindingDispositionIDApproved = 8
	// A quarantined file or other content was restored to its original location.
	SecurityFindingDispositionIDRestored = 9
	// A suspicious or risky entity was deemed to no longer be suspicious (re-scored).
	SecurityFindingDispositionIDExonerated = 10
	// A corrupt file or configuration was corrected.
	SecurityFindingDispositionIDCorrected = 11
	// A corrupt file or configuration was partially corrected.
	SecurityFindingDispositionIDPartiallyCorrected = 12
	// A corrupt file or configuration was not corrected.
	SecurityFindingDispositionIDUncorrected = 13
	// An operation was delayed, for example if a restart was required to finish the operation.
	SecurityFindingDispositionIDDelayed = 14
	// Suspicious activity or a policy violation was detected without further action.
	SecurityFindingDispositionIDDetected = 15
	// The outcome of an operation had no action taken.
	SecurityFindingDispositionIDNoAction = 16
	// The operation or action was logged without further action.
	SecurityFindingDispositionIDLogged = 17
	// A file or other entity was marked with extended attributes.
	SecurityFindingDispositionIDTagged = 18
	// The request or activity was detected as a threat and resulted in a notification but request
	// was not blocked.
	SecurityFindingDispositionIDAlert = 19
	// Counted the request or activity but did not determine whether to allow it or block it.
	SecurityFindingDispositionIDCount = 20
	// The request was detected as a threat and resulted in the connection being reset.
	SecurityFindingDispositionIDReset = 21
	// Required the end user to solve a CAPTCHA puzzle to prove that a human being is sending the
	// request.
	SecurityFindingDispositionIDCaptcha = 22
	// Ran a silent challenge that required the client session to verify that it's a browser, and
	// not a bot.
	SecurityFindingDispositionIDChallenge = 23
	// The requestor's access has been revoked due to security policy enforcements. Note: use the
	// Host profile if the User or Actor requestor is not present in the event class.
	SecurityFindingDispositionIDAccessRevoked = 24
	// A request or submission was rejected. For example, when a form was improperly filled out and
	// submitted. This is distinct from 2 'Blocked'.
	SecurityFindingDispositionIDRejected = 25
	// An attempt to access a resource was denied due to an authorization check that failed. This
	// is a more specific disposition than 2 'Blocked' and can be complemented with the
	// authorizations attribute for more detail.
	SecurityFindingDispositionIDUnauthorized = 26
	// An error occurred during the processing of the activity or request. Use the message
	// attribute of the base class for details.
	SecurityFindingDispositionIDError = 27
	// The disposition is not mapped. See the disposition attribute, which contains a data source
	// specific value.
	SecurityFindingDispositionIDOther = 99
)

